    assert.strictEqual(invocationCount, 1, `Expected 1 invocation, got ${invocationCount}`);
    assert.deepStrictEqual(lastArgs, ['d'], `Expected last args ['d'], got ${JSON.stringify(lastArgs)}`);
    console.log('all tests passed');
